def solve():
    run_rate = Q("33.5")
    phase = {1: Q("0.45"), 2: Q("0.75")}
    integ = {1: Q("53.5"), 2: Q(30)}
    tax = Q(28) / 100

    def net(year):
        # after-tax net cash flow for the year (tax credit applies at the same rate if negative)
        savings = run_rate * phase.get(year, Q(1))
        return (savings - integ.get(year, Q(0))) * (1 - tax)

    year1 = net(1)
    cum = Q(0)
    cum_end2 = None
    breakeven_year = None
    breakeven = None
    for k in range(1, 200):
        cf = net(k)
        start = cum
        cum = cum + cf
        if k == 2:
            cum_end2 = cum
        if breakeven_year is None and cum >= 0:
            breakeven_year = k
            if year1 >= 0:
                breakeven = Q(0)
            else:
                breakeven = (k - 1) + (-start) / cf
        if k >= 2 and breakeven_year is not None:
            break
    return {
        "final": breakeven,
        "year1_net_after_tax": year1,
        "cumulative_end_year2": cum_end2,
        "breakeven_year": breakeven_year,
    }

