            n = run * (1 - t)
        start = cum
        cum = cum + n
        if k == 2:
            cum_end2 = cum
        if be is None and cum >= 0:
            be = k
            if k == 1:
                result = Q(0)
            else:
                result = (k - 1) + (-start) / n
        if k >= 3 and be is not None:
            break
    if y1 >= 0:
        result = Q(0)
    return {
        "final": result,
        "year1_net_after_tax": y1,
        "cumulative_end_year2": cum_end2,
        "breakeven_year": be,
    }
